import os
from typing import List, Optional
from moler.util.moler_test import MolerTest  # type: ignore
from moler.exceptions import CommandFailure  # type: ignore
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console
from taf.ul.sc.perf.devices.ue.generic_rtg_cus import GenericRtgCus
from taf.ul.sc.uesim.cus.executor import Executor  # type: ignore
from taf.ul.sc.uesim.cus.workstation import Workstation  # type: ignore
from taf.ul.sc.uesim.rtg import Controller  # type: ignore
from taf.ul.sc.syslog import Syslog # type: ignore


class CUS(GenericRtgCus):
    def __init__(self,
                 executor: Optional[Executor] = None,
                 workstation: Optional[Workstation] = None,
                 controllers: Optional[List[Controller]] = None,
                 syslog: Optional[Syslog] = None
                 ):
        self.syslog = syslog
        super(CUS, self).__init__(executor=executor, workstation=workstation, controllers=controllers)

    @log_function_status_to_console(msg="Starting scenario", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def start_scenario(self, scenario_name):
        results = self.executor.start_cus_scenario(scenario_name=scenario_name)
        self.started_scenarios.append(results)

    @log_function_status_to_console(msg="Stopping scenario", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def stop_scenario(self):
        try:
            self.executor.stop_cus_scenario()
        except CommandFailure as exc:
            if "Test already in progress. Cannot proceed" in str(exc):
                self._restart_executor_after_exception(execute_after_restart=self.executor.stop_cus_scenario)
            else:
                raise exc

    @log_function_status_to_console(msg="Copy scenario file to WS", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def copy_scenario_file(self, source_scenario_path, destination_dir='/home/cus/test/scenarios/'):
        super(CUS, self).copy_scenario_file(source_scenario_path=source_scenario_path,
                                            destination_dir=destination_dir)

    @log_function_status_to_console(msg="Collect conf files: UE_CAP/UE_DB", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def collect_configuration(self, log_dir):
        if not self.started_scenarios:
            MolerTest.warning("Scenario not started. Cannot download CUS configuration")
            return

        last_execution = self.started_scenarios[-1]
        execution_dir = os.path.join(last_execution['SCENARIO'], last_execution['QUEUED_TIME'])
        self.ws.collect_cus_configuration_file(execution_dir, log_dir)
        self.ws.collect_dhcp_configuration_file(log_dir)
        self.ws.collect_ue_capabilities_file(execution_dir, log_dir)
        self.ws.collect_ue_db_file(execution_dir, log_dir)
        self.ws.collect_scenario_file(execution_dir=execution_dir,
                                      scenario_name=last_execution['SCENARIO'],
                                      destination_dir=log_dir)

    def start_syslog_collection(self):
        self.syslog.connect_to_syslog()
